import React, { useEffect, useState } from "react";
import "../Styles/CompanyJobs.css";

const CompanyJobs = () => {
  const [jobs, setJobs] = useState([]);
  const [editingIndex, setEditingIndex] = useState(null);
  const [editedJob, setEditedJob] = useState({});

  useEffect(() => {
    const storedJobs = JSON.parse(localStorage.getItem("jobs")) || [];
    setJobs(storedJobs);
  }, []);

  // 🗑 حذف وظيفة
  const handleDelete = (index) => {
    const updatedJobs = jobs.filter((_, i) => i !== index);
    setJobs(updatedJobs);
    localStorage.setItem("jobs", JSON.stringify(updatedJobs));
  };

  // ✏️ بدء التعديل
  const handleEdit = (index) => {
    setEditingIndex(index);
    setEditedJob(jobs[index]);
  };

  // ✅ حفظ التعديل
  const handleSave = () => {
    const updatedJobs = [...jobs];
    updatedJobs[editingIndex] = editedJob;
    setJobs(updatedJobs);
    localStorage.setItem("jobs", JSON.stringify(updatedJobs));
    setEditingIndex(null);
    alert("✅ Job updated successfully!");
  };

  // ❌ إلغاء التعديل
  const handleCancel = () => {
    setEditingIndex(null);
    setEditedJob({});
  };

  return (
    <div className="companyjobs-page">
      <h1 className="companyjobs-title">
        My <span className="accent">Posted Jobs</span>
      </h1>

      {jobs.length === 0 ? (
        <p className="no-jobs">No jobs posted yet.</p>
      ) : (
        jobs.map((job, index) => (
          <div key={index} className="job-card">
            {editingIndex === index ? (
              <>
                <input
                  type="text"
                  value={editedJob.jobTitle}
                  onChange={(e) =>
                    setEditedJob({ ...editedJob, jobTitle: e.target.value })
                  }
                  className="edit-input"
                />
                <input
                  type="text"
                  value={editedJob.organization}
                  onChange={(e) =>
                    setEditedJob({ ...editedJob, organization: e.target.value })
                  }
                  className="edit-input"
                />
                <textarea
                  value={editedJob.description}
                  onChange={(e) =>
                    setEditedJob({ ...editedJob, description: e.target.value })
                  }
                  className="edit-input"
                />
                <div className="edit-buttons">
                  <button className="btn-save" onClick={handleSave}>
                    Save
                  </button>
                  <button className="btn-cancel" onClick={handleCancel}>
                    Cancel
                  </button>
                </div>
              </>
            ) : (
              <>
                <div className="job-header">
                  <h3>{job.jobTitle}</h3>
                  <span className="rate">
                    {job.rate} OMR · {job.rateType}
                  </span>
                </div>
                <p className="org-name">{job.organization}</p>
                <p className="desc">{job.description}</p>
                <p className="skills">Skills: {job.skills}</p>

                <div className="job-actions">
                  <button
                    className="btn-edit"
                    onClick={() => handleEdit(index)}
                  >
                    ✏️ Edit
                  </button>
                  <button
                    className="btn-delete"
                    onClick={() => handleDelete(index)}
                  >
                    🗑 Delete
                  </button>
                </div>
              </>
            )}
          </div>
        ))
      )}
    </div>
  );
};

export default CompanyJobs;
